SELECT (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_listing' AND ((table_name='listing_rag_revision' AND column_name IN ('listing_id','revision','tombstone','content_hash','latest_event_id','updated_at')) OR (table_name='listing_rag_grant' AND column_name IN ('actor_user_id','resource_id','operation','active','version','managed_by','updated_at')) OR (table_name='listing_rag_outbox' AND column_name IN ('event_id','listing_id','revision','content_hash','payload','state','attempts','next_attempt_at','lease_until','lease_token','error_code','created_at'))))=25 AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='bk_listing' AND table_name IN ('listing_rag_revision','listing_rag_grant','listing_rag_outbox') AND engine='InnoDB')=3;
